name: Verify CI scope
description: Revalidate documentation eligibility against the actual checked-out PR merge.
inputs:
  full:
    description: Expected selection; true conservatively runs everything, false must be independently proved, auto selects.
    default: 'true'
  upstream_result:
    description: The selector must have succeeded; missing or failed selection never permits skipped work.
    default: success
outputs:
  full:
    description: Whether this source requires full product verification.
    value: ${{ steps.scope.outputs.full }}
runs:
  using: composite
  steps:
    - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
      with:
        node-version: '22'
    - id: scope
      shell: bash
      working-directory: ${{ github.workspace }}
      env:
        EXPECTED_FULL: ${{ inputs.full }}
        UPSTREAM_RESULT: ${{ inputs.upstream_result }}
      run: node scripts/ci/docs-scope.mjs --expected-full "$EXPECTED_FULL" --upstream-result "$UPSTREAM_RESULT"
name: Select CI scope

on:
  workflow_call:
    outputs:
      full:
        description: Full verification is required unless this exact PR merge contains only inert documentation.
        value: ${{ jobs.select.outputs.full }}

permissions:
  contents: read

jobs:
  select:
    name: Classify CI scope
    runs-on: ubuntu-latest
    timeout-minutes: 5
    outputs:
      full: ${{ steps.scope.outputs.full }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 2
          persist-credentials: false
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: auto
/** Registered development contracts shared by selection and structural checks. */
import path from "node:path";
import { readFile, realpath, stat } from "node:fs/promises";
import { rustPackages } from "../pr-platform/rust-packages.mjs";

export const contractFiles = [
  "scripts/validation/validation.json",
  "frontend/validation.json",
  ...rustPackages.map(({ directory }) => `${directory}/validation.json`),
];

/** Read a regular repository file without following a symlink outside root. */
export async function readRepositoryFile(root, file) {
  if (
    typeof file !== "string" ||
    !file ||
    path.isAbsolute(file) ||
    file.split("/").includes("..") ||
    /[\\\x00-\x1f\x7f]/u.test(file)
  )
    throw Error(`Unsafe repository path: ${file}`);
  const base = await realpath(root);
  const resolved = await realpath(path.resolve(base, file));
  const relative = path.relative(base, resolved);
  if (
    !relative ||
    relative === ".." ||
    relative.startsWith(`..${path.sep}`) ||
    path.isAbsolute(relative)
  )
    throw Error(`Repository path escapes root: ${file}`);
  if (!(await stat(resolved)).isFile())
    throw Error(`Not a regular file: ${file}`);
  return readFile(resolved, "utf8");
}

export async function loadContracts(root) {
  const contracts = [];
  for (const file of contractFiles) {
    try {
      const parsed = JSON.parse(await readRepositoryFile(root, file));
      if (parsed.schema !== 1 || !Array.isArray(parsed.contracts))
        throw Error("expected schema 1 and a contracts array");
      contracts.push(...parsed.contracts);
    } catch (error) {
      throw Error(`Invalid validation contract: ${file}: ${error.message}`);
    }
  }
  return contracts;
}

