name: Verify CI scope
description: Revalidate documentation eligibility against the actual checked-out PR merge.
inputs:
  full:
    description: Expected selection; true conservatively runs everything, false must be independently proved, auto selects.
    default: 'true'
  upstream_result:
    description: The selector must have succeeded; missing or failed selection never permits skipped work.
    default: success
outputs:
  full:
    description: Whether this source requires full product verification.
    value: ${{ steps.scope.outputs.full }}
runs:
  using: composite
  steps:
    - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
      with:
        node-version: '22'
    - id: scope
      shell: bash
      working-directory: ${{ github.workspace }}
      env:
        EXPECTED_FULL: ${{ inputs.full }}
        UPSTREAM_RESULT: ${{ inputs.upstream_result }}
      run: node scripts/ci/docs-scope.mjs --expected-full "$EXPECTED_FULL" --upstream-result "$UPSTREAM_RESULT"
name: Code Quality and Health Check

# Portable checks run independently of native builds and browsers. CI owns Rust
# workspace compilation/unit tests; UI E2E owns full Chromium on all platforms.
# scripts/check-health.sh remains the standalone comprehensive local gate.
on:
  workflow_call:
    inputs:
      full:
        type: string
        default: 'true'
      upstream_result:
        type: string
        default: success
  schedule:
    - cron: '0 6 * * 1'
  workflow_dispatch:

concurrency:
  group: health-${{ github.workflow }}-${{ github.event_name }}-${{ github.event.pull_request.number || github.ref }}-${{ github.event_name == 'push' && github.run_id || 'candidate' }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' || github.event_name == 'merge_group' }}

permissions:
  contents: read

env:
  CARGO_TERM_COLOR: always

jobs:
  platform:
    if: ${{ !cancelled() }}
    name: Portable checks (${{ matrix.os }})
    runs-on: ${{ (inputs.full || 'true') == 'true' && matrix.os || 'ubuntu-latest' }}
    timeout-minutes: 25
    strategy:
      fail-fast: false
      matrix:
        os: [ubuntu-latest, macos-26-intel, windows-latest]
    defaults:
      run:
        shell: bash
    steps:
      - uses: actions/checkout@v7.0.1
        with:
          fetch-depth: 2
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ (inputs.full || 'true') }}
          upstream_result: ${{ inputs.upstream_result || 'success' }}
      - name: Reserve Health cleanup and diagnostic evidence time
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: echo "MESH_HEALTH_DEADLINE_MS=$(( $(date +%s) * 1000 + 23 * 60000 ))" >> "$GITHUB_ENV"
      - uses: actions/setup-node@v7.1.0
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          node-version: '22'
          cache: npm
          cache-dependency-path: frontend/package-lock.json
      - uses: actions/setup-python@v7
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          python-version: '3.12'
      - name: Install pinned native inspection toolchain
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: python scripts/release/sevenzip.py install
      - name: Install frontend dependencies
        if: ${{ steps.scope.outputs.full == 'true' }}
        working-directory: frontend
        run: npm ci
      - name: Frontend static checks
        if: ${{ steps.scope.outputs.full == 'true' && (runner.os == 'Linux') }}
        working-directory: frontend
        run: |
          npm run format:check
          npm run lint
          npm run typecheck
      - name: Audit frontend dependencies
        if: ${{ steps.scope.outputs.full == 'true' && (runner.os == 'Linux') }}
        working-directory: frontend
name: Windows workspace archive

on:
  workflow_call:
    inputs:
      full:
        type: string
        default: 'true'
      upstream_result:
        type: string
        default: success
      diagnostic_timing:
        type: boolean
        default: false

permissions:
  contents: read

env:
  CARGO_TERM_COLOR: never
  # Both producer and consumers keep the same ordinary Cargo profile inputs.
  CARGO_PROFILE_DEV_DEBUG: line-tables-only
  CARGO_PROFILE_TEST_DEBUG: line-tables-only
  RUST_TEST_THREADS: '1'
  MESH_TALK_TEST_TIMING: ${{ inputs.diagnostic_timing && '1' || '0' }}

jobs:
  build:
    if: ${{ !cancelled() }}
    name: Windows workspace build
    runs-on: ${{ (inputs.full || 'true') == 'true' && 'windows-latest' || 'ubuntu-latest' }}
    timeout-minutes: 60
    outputs:
      rust: ${{ steps.compiler.outputs.rust }}
    defaults:
      run:
        shell: bash
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          fetch-depth: 2
          ref: ${{ github.sha }}
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ (inputs.full || 'true') }}
          upstream_result: ${{ inputs.upstream_result || 'success' }}
      - name: Use runner-owned native temporary storage
        if: ${{ steps.scope.outputs.full == 'true' }}
        shell: pwsh
        run: |
          Write-Host "Native temporary storage: $([IO.Path]::GetTempPath()) -> $env:RUNNER_TEMP"
          "TEMP=$env:RUNNER_TEMP" >> $env:GITHUB_ENV
          "TMP=$env:RUNNER_TEMP" >> $env:GITHUB_ENV
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: frontend/package-lock.json
      - name: Validate Windows native build dependencies
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: node scripts/ci/windows-native-deps.mjs
      - uses: dtolnay/rust-toolchain@stable
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          components: clippy, rustfmt, llvm-tools-preview
      - name: Pin producer compiler for consumers
        if: ${{ steps.scope.outputs.full == 'true' }}
        id: compiler
        run: rustc --version | awk '{print "rust=" $2}' >> "$GITHUB_OUTPUT"
      - uses: Swatinem/rust-cache@v2
        if: ${{ steps.scope.outputs.full == 'true' }}
        env:
          CARGO_TERM_COLOR: always
          RUST_TEST_THREADS: ''
        with:
          save-if: ${{ github.ref == 'refs/heads/main' }}
          workspaces: . -> target
          shared-key: workspace-checks-checks
          cache-on-failure: true
      - name: Frontend dependencies and structural checks
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: |
          npm ci --prefix frontend
          node scripts/validation/standards.mjs
          node scripts/check-repository-hygiene.mjs
      - uses: taiki-e/install-action@v2.87.31
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          if-no-files-found: error
          retention-days: 14

  ui-gate:
    name: Playwright UI E2E
    needs: [linux, desktop, coverage, packs, portable-evidence, portable, chromium-extended, firefox-extended, scope]
    if: ${{ !cancelled() }}
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          fetch-depth: 2
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ needs.scope.outputs.full }}
          upstream_result: ${{ needs.scope.result }}
      - name: Require complete selected UI matrices
        if: ${{ steps.scope.outputs.full == 'true' }}
        env:
          LINUX: ${{ needs.linux.result }}
          DESKTOP: ${{ needs.desktop.result }}
          COVERAGE: ${{ needs.coverage.result }}
          PACKS: ${{ needs.packs.result }}
          CHROMIUM: ${{ needs.portable-evidence.result }}
          PORTABLE: ${{ needs.portable.result }}
          EXTENDED_CHROMIUM: ${{ needs.chromium-extended.result }}
          FIREFOX: ${{ needs.firefox-extended.result }}
          EXTENDED: ${{ github.event_name == 'schedule' || (github.event_name == 'workflow_dispatch' && inputs.extended) }}
        run: |
          test "$LINUX" = success
          test "$DESKTOP" = success
          test "$COVERAGE" = success
          test "$PACKS" = success
          test "$CHROMIUM" = success
          test "$PORTABLE" = success
          test "$FIREFOX" = success
          if [ "$EXTENDED" = true ]; then
            test "$EXTENDED_CHROMIUM" = success
          else
            test "$EXTENDED_CHROMIUM" = skipped
          if-no-files-found: error

  asan:
    name: ASan + LeakSanitizer (core)
    needs: [cohort, shards, scope]
    if: ${{ !cancelled() }}
    runs-on: ubuntu-latest
    env:
      MESH_ASAN_TOOLCHAIN: ${{ needs.cohort.outputs.toolchain }}
      MESH_ASAN_RUSTC: ${{ needs.cohort.outputs.rustc }}
      MESH_ASAN_CARGO: ${{ needs.cohort.outputs.cargo }}
      MESH_ASAN_ARCHIVE_SHA256: ${{ needs.cohort.outputs.archive_sha256 }}
      MESH_ASAN_MANIFEST_SHA256: ${{ needs.cohort.outputs.manifest_sha256 }}
      MESH_ASAN_SHARDS_RESULT: ${{ needs.shards.result }}
      MESH_ASAN_BUILD_RESULT: ${{ needs.cohort.result }}
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 2
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ needs.scope.outputs.full }}
          upstream_result: ${{ needs.scope.result }}
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          node-version: 22
      - name: Download this attempt's ASan evidence
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: actions/download-artifact@v8
        with:
          pattern: asan-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}-shard-*
          path: tmp/asan-union
      - name: Verify every actual shard and complete exact-source union
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: node scripts/ci/asan.mjs verify tmp/asan-union
"}

